import { Group, PlaneGeometry, MeshBasicNodeMaterial, Mesh, DoubleSide } from 'three/webgpu';

function createNode(config, ctx) {
    const group = new Group();

    // --- Plane with texture ---
    // Determine size from aspect ratio of source rect (512 × 320)
    const width = 1.5; // arbitrary, could be driven by design
    const height = width * (320 / 512);
    const geometry = new PlaneGeometry(width, height);
    const texture = ctx.textureLoader.load(config.imageUrl);
    const material = new MeshBasicNodeMaterial({
        map: texture,
        side: DoubleSide,
    });
    const mesh = new Mesh(geometry, material);
    group.add(mesh);

    // --- Text overlay ---
    let textMesh = null;
    if (config.textContent && config.textContent.headline) {
        const fontSize = 0.34; // scene-unit height (headline token)
        textMesh = ctx.fontAtlas.createText({
            text: config.textContent.headline,
            fontFamily: 'Lora',
            fontWeight: 400,
            fontSize,
            color: '#e8ecf2', // paper
        });
        textMesh.position.set(0, 0, 0.01); // slightly forward
        group.add(textMesh);
    }

    // --- Scene placement ---
    const pos = config.scenePosition || { x: 0, y: 0, z: 0 };
    const rot = config.sceneRotation || { x: 0, y: 0, z: 0 };
    const scl = config.sceneScale || { x: 1, y: 1, z: 1 };
    group.position.set(pos.x, pos.y, pos.z);
    group.rotation.set(rot.x, rot.y, rot.z);
    group.scale.set(scl.x, scl.y, scl.z);

    // --- Event handlers (none) ---
    group.userData.handlers = {};

    // --- Cleanup ---
    group.userData.cleanup = () => {
        geometry.dispose();
        material.dispose();
        if (texture) texture.dispose();
        if (textMesh) {
            if (textMesh.geometry) textMesh.geometry.dispose();
            if (textMesh.material) textMesh.material.dispose();
        }
        // No GSAP timelines for this node
    };

    // Apply any cinematic primitives (none for this spec)
    if (config.cinematicPrimitives && config.cinematicPrimitives.length > 0) {
        config.cinematicPrimitives.forEach(primitive => {
            ctx.primitives[primitive.name](group, primitive.params);
        });
    }

    return group;
}

export default createNode;
